import "server-only";
import type { Prisma } from "@/generated/prisma/client";
import { EntitlementError, readEntitlements } from "@/lib/entitlements";
import { AppError } from "@/lib/errors";

// Caller holds the User lock for writes. Reads resolve the same deterministic fallback.
export async function resolveFreeTemplate(
  tx: Prisma.TransactionClient,
  userId: string,
) {
  const user = await tx.user.findUniqueOrThrow({
    where: { id: userId },
    select: { freeTemplateId: true },
  });
  const selected = user.freeTemplateId
    ? await tx.template.findFirst({
        where: { id: user.freeTemplateId, userId, archivedAt: null },
        select: { id: true },
      })
    : null;
  return (
    selected?.id ??
    (
      await tx.template.findFirst({
        where: { userId, archivedAt: null },
        orderBy: [{ createdAt: "asc" }, { id: "asc" }],
        select: { id: true },
      })
    )?.id ??
    null
  );
}
export async function maintainFreeTemplate(
  tx: Prisma.TransactionClient,
  userId: string,
) {
  const id = await resolveFreeTemplate(tx, userId);
  await tx.user.update({ where: { id: userId }, data: { freeTemplateId: id } });
  return id;
}
export async function requireTemplateAccess(
  tx: Prisma.TransactionClient,
  userId: string,
  templateId?: string,
) {
  const access = await readEntitlements(userId, tx);
  if (!access.features.templateUse)
    throw new EntitlementError(access.reasons.templateUse!);
  if (
    templateId &&
    !(await tx.template.findFirst({
      where: { id: templateId, userId, archivedAt: null },
      select: { id: true },
    }))
  )
    throw new AppError("Template not found.");
  if (access.limits.savedTemplates === null) return;
  if (templateId) {
    if (templateId !== (await resolveFreeTemplate(tx, userId)))
      throw new EntitlementError("UPGRADE_REQUIRED");
  } else if (
    (await tx.template.count({ where: { userId, archivedAt: null } })) >=
    access.limits.savedTemplates
  )
    throw new EntitlementError("UPGRADE_REQUIRED");
}
